def comps_conn(G, conn=8):
 H,W=G.shape; seen=set(); out=[]
 steps=[(i,j) for i in [-1,0,1] for j in [-1,0,1] if (i or j) and (conn==8 or abs(i)+abs(j)==1)]
 for r in range(H):
  for c in range(W):
   if G[r,c]==0 and (r,c) not in seen:
    st=[(r,c)];seen.add((r,c)); pts=[]
    while st:
     x,y=st.pop();pts.append((x,y))
     for dx,dy in steps:
      z=x+dx,y+dy
      if 0<=z[0]<H and 0<=z[1]<W and G[z]==0 and z not in seen:seen.add(z);st.append(z)
    out.append(pts)
 return out
